import{_ as i,o as s,c as e,ai as t}from"./chunks/framework.CGsC_gYW.js";const k=JSON.parse('{"title":"安装部署","description":"","frontmatter":{"title":"安装部署"},"headers":[],"relativePath":"qiantao/install.md","filePath":"qiantao/install.md","lastUpdated":1792576248000}'),l={name:"qiantao/install.md"};function n(o,a,d,p,c,h){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="klkhk-plugin-qiandao-1-12-2-·-安装部署" tabindex="-1">[klkhk]plugin_qiandao_1.12.2 · 安装部署 <a class="header-anchor" href="#klkhk-plugin-qiandao-1-12-2-·-安装部署" aria-label="Permalink to &quot;[klkhk]plugin_qiandao_1.12.2 · 安装部署&quot;">​</a></h1><blockquote><p>装插件最容易翻车的不是步骤，是版本。先花 30 秒确认下面两行，能省掉后面半小时。</p></blockquote><h2 id="一、装之前先确认" tabindex="-1">一、装之前先确认 <a class="header-anchor" href="#一、装之前先确认" aria-label="Permalink to &quot;一、装之前先确认&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th><th>怎么查</th></tr></thead><tbody><tr><td>服务端核心</td><td>Spigot / Paper <strong>1.12.2</strong></td><td>启动日志第一行，或游戏内 <code>/version</code></td></tr><tr><td>Java</td><td><strong>8</strong> 及以上</td><td>控制台执行 <code>java -version</code></td></tr><tr><td>可选前置</td><td>Vault、PlayerPoints、ZPoints</td><td>按需，不装也能签到</td></tr></tbody></table><blockquote><p>这是 1.12.2 专用构建，材质名和音效名都按 1.12.2 的规范写死。丢进 1.13+ 会报材质找不到，丢进 1.8 会报 API 不存在 —— 不是配置问题，是版本问题。</p></blockquote><h2 id="二、安装" tabindex="-1">二、安装 <a class="header-anchor" href="#二、安装" aria-label="Permalink to &quot;二、安装&quot;">​</a></h2><ol><li>打开 <a href="https://github.com/zhaobuobuo114/klkhk-plugin_qiandao/releases/latest" target="_blank" rel="noreferrer">Releases</a>，下载 <code>[klkhk]plugin_qiandao_1.12.2.jar</code>。GitHub 会把文件名里的方括号显示成点号（<code>klkhk.plugin_qiandao_1.12.2.jar</code>），是同一个文件。</li><li>把 jar 放进服务端根目录的 <code>plugins/</code>。在线人数多的话建议停服操作，别热插拔。</li><li>启动服务器。看到这两行，说明插件活过来了：</li></ol><div class="language-log vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[QianDao] QianDao 签到插件已启用 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">v1.1.4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[QianDao] 金币联动: ZPOINTS</span></span></code></pre></div><p>如果第二行是 <code>金币联动: 已关闭</code>，不是插件坏了 —— 是你没装对应经济插件，签到功能完全正常，只是不发金币。</p><ol start="4"><li>插件会自己生成这两个文件：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/QianDao/config.yml    奖励、金币、消息、音效</span></span>
<span class="line"><span>plugins/QianDao/data.yml      玩家数据（第一个人签到后才有）</span></span></code></pre></div><ol start="5"><li>改完 <code>config.yml</code> 执行 <code>/qd reload</code>，不用重启。</li></ol><h2 id="三、升级-这一步别偷懒" tabindex="-1">三、升级（这一步别偷懒） <a class="header-anchor" href="#三、升级-这一步别偷懒" aria-label="Permalink to &quot;三、升级（这一步别偷懒）&quot;">​</a></h2><p>正确顺序是：<strong>备份 → 删旧配置 → 换 jar → 重启 → 迁回自定义值 → 重载</strong>。</p><ol><li>备份 <code>plugins/QianDao/config.yml</code> 和 <code>data.yml</code></li><li>删除旧 <code>config.yml</code></li><li>替换 jar，重启</li><li>把备份里的自定义内容（奖励、金币、消息）迁到新配置</li><li><code>/qd reload</code> 校验</li></ol><blockquote><p>为什么不直接覆盖 jar？新版本可能新增配置项，旧的 <code>config.yml</code> 不会自动补全。结果通常是「功能没生效，控制台也不报错」—— 这种问题最难查，不如一次做对。</p></blockquote><p><code>data.yml</code> 不用删，里面的玩家数据是向下兼容的。</p><h2 id="四、卸载" tabindex="-1">四、卸载 <a class="header-anchor" href="#四、卸载" aria-label="Permalink to &quot;四、卸载&quot;">​</a></h2><ol><li>停服</li><li>需要留数据就先备份 <code>plugins/QianDao/data.yml</code></li><li>删掉整个 <code>plugins/QianDao/</code> 目录</li><li>删掉 <code>plugins/</code> 下的插件 jar</li><li>启动服务器</li></ol><h2 id="五、目录结构" tabindex="-1">五、目录结构 <a class="header-anchor" href="#五、目录结构" aria-label="Permalink to &quot;五、目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>服务器根目录/</span></span>
<span class="line"><span>├─ plugins/</span></span>
<span class="line"><span>│  ├─ [klkhk]plugin_qiandao_1.12.2.jar</span></span>
<span class="line"><span>│  └─ QianDao/</span></span>
<span class="line"><span>│     ├─ config.yml      # 奖励、金币、消息、音效</span></span>
<span class="line"><span>│     └─ data.yml        # 玩家签到数据（UUID 索引）</span></span></code></pre></div><h2 id="六、自己编译" tabindex="-1">六、自己编译 <a class="header-anchor" href="#六、自己编译" aria-label="Permalink to &quot;六、自己编译&quot;">​</a></h2><p>需要 JDK 8 和 Maven：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/zhaobuobuo114/klkhk-plugin_qiandao.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> klkhk-plugin_qiandao</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span></code></pre></div><p>产物在 <code>target/QianDao.jar</code>。</p><p><code>plugins/</code> 下的 <code>Vault-1.7.3.jar</code>、<code>PlayerPoints-2.1.5.jar</code>、<code>zpoints-1.3.0.jar</code> 是编译期依赖，不会打进最终 jar，运行时由服务端提供。想换 API 版本就改 <code>pom.xml</code> 里的 <code>spigot-api</code>，但材质和音效名要跟着改。</p><hr><p>下一步：<a href="/plugin-wiki/qiantao/commands">指令与权限</a> →</p>`,28)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
